#!/usr/bin/env node
/**
 * Bundle docs/games/*.md into a TS module the web app imports, so the in-app
 * per-game Guide tab always ships the same content as the repo docs — no
 * runtime filesystem or network reads. Runs as part of `pnpm --filter web build`
 * (and dev); the generated file is checked in so a stale checkout still builds.
 */
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const srcDir = join(root, "docs", "games");
const outFile = join(root, "apps", "web", "lib", "game-docs.generated.ts");

const files = readdirSync(srcDir)
  .filter((f) => f.endsWith(".md") && f !== "README.md")
  .sort();

const entries = files.map((f) => {
  // Slug → Game enum value: "seven-days" → "SEVEN_DAYS".
  const key = f.replace(/\.md$/, "").toUpperCase().replace(/-/g, "_");
  const content = readFileSync(join(srcDir, f), "utf8");
  return `  ${key}: ${JSON.stringify(content)},`;
});

const out = `// GENERATED by scripts/generate-game-docs.mjs from docs/games/*.md — do not edit.
// Regenerated on every web build; edit the markdown files instead.

export const GAME_DOCS: Record<string, string> = {
${entries.join("\n")}
};
`;

writeFileSync(outFile, out, "utf8");
console.log(`game-docs: bundled ${files.length} guides -> apps/web/lib/game-docs.generated.ts`);
